import{_ as o,C as s,o as i,c as n,a6 as t,E as r}from"./chunks/framework.CKIbuWFA.js";const v=JSON.parse('{"title":"Instale e gerencie plugins","description":"","frontmatter":{"title":"Instale e gerencie plugins","docId":"user.plugins.index","translationKey":"user.plugins.index","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"93c8811682d0baa5bd18b571503fce483cf1f464e94b94bc933241bf277d23d4","translationRevision":"95af5efddcbb1f448b6d8ade8234685b5acf6abac54afca69dbff9648f5ced77","order":10},"headers":[],"relativePath":"pt/user/plugins/index.md","filePath":"pt/user/plugins/index.md","lastUpdated":1794611623000}'),d={name:"pt/user/plugins/index.md"};function l(c,e,u,p,m,f){const a=s("DemoFrame");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="install-and-manage-plugins" tabindex="-1">Instale e gerencie plugins <a class="header-anchor" href="#install-and-manage-plugins" aria-label="Permalink to &quot;Instale e gerencie plugins {#install-and-manage-plugins}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Adicione uma integração, revise o acesso solicitado e confirme que suas ações podem ser usadas. Você precisa de um pacote de desktop compatível com o sistema operacional, a arquitetura e a versão de host do plugin. Operações de catálogo remoto e download exigem acesso à rede; alguns serviços baseados em conta também exigem <a href="./../cloud/account.html">login no Cloud</a>.</p><h2 id="review-before-enabling" tabindex="-1">Revise antes de ativar <a class="header-anchor" href="#review-before-enabling" aria-label="Permalink to &quot;Revise antes de ativar {#review-before-enabling}&quot;">​</a></h2><ol><li>Abra <strong>Plugins</strong> e inspecione Installed, Explore ou Updates. Explore solicita apenas itens de plugins. Encontre modelos de automação e perfis em <a href="./../automations/templates.html">Automations</a>.</li><li>Selecione um plugin para inspecionar descrição, versão, compatibilidade e ambiente de execução. Confira o publicador e as capacidades ou permissões solicitadas, em vez de confiar apenas em um nome de exibição conhecido.</li><li>Use o fluxo de instalação para inspecionar a prévia do pacote. Revise a versão exata, informações de assinatura, acesso solicitado e alterações em relação à versão instalada antes de confirmar a instalação.</li><li>Aguarde o resultado da tarefa do pacote. Baixar, instalar e ativar são etapas distintas; um cartão de catálogo sozinho não significa que o ambiente de execução está pronto.</li><li>Abra o painel Settings ou Connection do plugin. Forneça o endereço do serviço e as credenciais apenas nos campos destinados a isso. Use uma verificação de conexão declarada quando disponível.</li><li>Ative o plugin e confira se seus tipos de ação ou páginas aparecem. Crie uma <a href="./../automations/first-rule.html">regra de registro</a> com escopo restrito antes de associar uma ação externa poderosa.</li></ol><p>Plugins podem executar código nativo ou processos separados. Um limite de processo pode isolar uma falha, mas não é uma sandbox do sistema operacional. Instale software de publicadores em quem confia. Uma assinatura válida identifica a procedência revisada do pacote; não torna todo efeito adequado ao seu fluxo.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Revisão de pacotes, tarefas de instalação, preferências de plugins e gerenciamento de versões estão disponíveis. As ações reais dependem do manifesto instalado, das capacidades do host e do serviço externo. Processadores de eventos têm seu próprio painel e podem adicionar campos opcionais de análise aos eventos; os campos brutos permanecem distintos.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Para uma falha de instalação, leia o erro da tarefa para problemas de compatibilidade, assinatura, ambiente de execução ou download. Não enfraqueça a verificação apenas para eliminar um erro. Se uma atualização causar problemas, inspecione as versões mantidas e use a reversão quando disponível. Revise automações dependentes antes de desativar ou desinstalar um plugin. Mantenha <a href="./../preferences/backups.html">backups</a> dos dados e configurações de plugins antes de removê-los.</p>',10)),r(a,{scenario:"plugins",locale:"pt",tour:"plugin",title:"Demonstração: plugins"})])}const b=o(d,[["render",l]]);export{v as __pageData,b as default};
